def process(noaaWildfires) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    df = noaaWildfires.copy()

    # Identify likely month/date column
    date_col = None
    for c in ['date', 'acq_date', 'fire_date', 'start_date', 'DISCOVERY_DATE', 'discovery_date']:
        if c in df.columns:
            date_col = c
            break

    if date_col is not None:
        d = pd.to_datetime(df[date_col], errors='coerce')
        july_mask = d.dt.month.eq(7)
    elif 'month' in df.columns:
        july_mask = pd.to_numeric(df['month'], errors='coerce').eq(7)
    elif 'MONTH' in df.columns:
        july_mask = pd.to_numeric(df['MONTH'], errors='coerce').eq(7)
    else:
        # fallback: try a column containing month name
        monthname_col = None
        for c in df.columns:
            if 'month' in c.lower() and df[c].dtype == object:
                monthname_col = c
                break
        if monthname_col is not None:
            july_mask = df[monthname_col].astype(str).str.strip().str.lower().isin(['jul', 'july', '07', '7'])
        else:
            july_mask = pd.Series([True]*len(df), index=df.index)

    # Identify fire size and median wind speed columns by common names
    size_candidates = [
        'fire_size', 'FIRE_SIZE', 'size', 'SIZE', 'acres', 'ACRES', 'area', 'AREA', 'burned_area', 'BURNED_AREA'
    ]
    wind_candidates = [
        'median_wind_speed', 'MEDIAN_WIND_SPEED', 'wind_speed_median', 'WIND_SPEED_MEDIAN',
        'wind_median', 'WIND_MEDIAN', 'med_wind', 'MED_WIND', 'ws_median'
    ]

    size_col = next((c for c in size_candidates if c in df.columns), None)
    wind_col = next((c for c in wind_candidates if c in df.columns), None)

    # If not found, attempt fuzzy match
    if size_col is None:
        for c in df.columns:
            cl = c.lower()
            if ('fire' in cl and 'size' in cl) or cl in ['acres', 'area', 'burned_area']:
                size_col = c
                break
    if wind_col is None:
        for c in df.columns:
            cl = c.lower()
            if 'median' in cl and 'wind' in cl and ('speed' in cl or 'spd' in cl):
                wind_col = c
                break

    if size_col is None or wind_col is None:
        # return diagnostic for missing columns
        return pd.DataFrame([{ 
            'size_col': size_col, 'wind_col': wind_col,
            'corr_pearson': np.nan, 'n': 0
        }])

    sub = df.loc[july_mask, [size_col, wind_col]].copy()
    sub[size_col] = pd.to_numeric(sub[size_col], errors='coerce')
    sub[wind_col] = pd.to_numeric(sub[wind_col], errors='coerce')
    sub = sub.dropna()

    n = len(sub)
    corr = sub[size_col].corr(sub[wind_col], method='pearson') if n >= 2 else np.nan

    return pd.DataFrame([{ 
        'size_col': size_col, 'wind_col': wind_col,
        'corr_pearson': corr, 'n': n
    }])

def process(julyFireWindCorr) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    row = julyFireWindCorr.iloc[0].to_dict() if len(julyFireWindCorr) else {}
    corr = row.get('corr_pearson', np.nan)

    # Define "strong" correlation as absolute Pearson r >= 0.7
    strong = False
    if corr is not None and not (isinstance(corr, float) and np.isnan(corr)):
        strong = abs(float(corr)) >= 0.7

    return pd.DataFrame([{'answer': 'Yes' if strong else 'No', 'corr_pearson': corr, 'n': row.get('n', None)}])

def load() -> pd.DataFrame:
